227	test('invoiceTotals calculates discount and VAT from tier', () => {
228	  const r = createInvoice({
229	    customerId: 'C-001',
230	    issueDate: '2026-10-07',
231	    lines: [
232	      { sku: 'DES-HOUR', qty: 8 },
233	      { sku: 'LOGO-PACK', qty: 2 },
234	    ],
235	  });
236	  assert.equal(r.ok, true);
237	  const totals = invoiceTotals(r.value);
238	  const lineTotal1 = 8 * 8500;
239	  const lineTotal2 = 2 * 120000;
240	  const subtotal = lineTotal1 + lineTotal2;
241	  const discount1 = lineTotal1 * 0.05;
242	  const discount2 = lineTotal2 * 0.05;
243	  const discount = discount1 + discount2;
244	  const amountAfterDiscount1 = lineTotal1 - discount1;
245	  const amountAfterDiscount2 = lineTotal2 - discount2;
246	  const vat1 = Math.round(amountAfterDiscount1 * 0.21);
247	  const vat2 = Math.round(amountAfterDiscount2 * 0.21);
248	  const vat = vat1 + vat2;
249	  assert.equal(totals.subtotal, subtotal);
250	  assert.equal(totals.discount, discount);
251	  assert.equal(totals.vat, vat);
252	  assert.equal(totals.total, subtotal - discount + vat);
253	});
